"""Publish specialist evidence without counting unavailable data as completion."""
import html
import json
from pathlib import Path
from neurofusion.data import save_json
root=Path(__file__).resolve().parents[1];out=root/'experiments/additional-specialists-001';out.mkdir(exist_ok=True)
registry=json.loads((root/'configs/additional_specialists.json').read_text())
eeg=root/'experiments/eeg-pilot-001/summary.json'
if eeg.exists():
    result=json.loads(eeg.read_text());proof=json.loads((eeg.parent/'verification.json').read_text());assert proof['passed']
    entry=next(r for r in registry['specialists'] if r['id']=='eeg')
    entry.update(status='trained_pilot_evaluated',trained=True,remaining='Six-patient label-selected pilot only. Expand cohort/recordings, assess event false alarms and latency, and perform independent qualification.')
    registry['eeg_pilot']={k:v for k,v in result.items() if k not in ['history','records']}
registry.update(all_specialists_complete=False,independently_qualified_specialists=0)
save_json(out/'summary.json',registry)
rows=''.join('<tr><td>'+html.escape(r['name'])+'</td><td>'+html.escape(r['status'])+'</td><td>'+html.escape(r['remaining'])+'</td></tr>' for r in registry['specialists'])
extra=''
if 'eeg_pilot' in registry:
    r=registry['eeg_pilot'];extra=f'<h2>EEG pilot</h2><p>12 recordings, four training patients and two validation patients. Matched {r["matched_events"]}/{r["reference_events"]} reference events; {r["false_alarms_per_background_hour"]:.2f} false alarms per background hour. This label-selected subset is not representative screening evaluation. Final checkpoint reproduced; not independently qualified.</p>'
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Additional specialists</title><style>body{font:16px system-ui;max-width:1100px;margin:30px auto;padding:20px;background:#101e2c;color:#eee}td,th{padding:12px;text-align:left;border-bottom:1px solid #456}a{color:#80ded0}</style><h1>Additional specialists: evidence and remaining work</h1><p>These branches are not all complete. No CT, aneurysm or longitudinal training datasets were supplied. Input checks and synthetic software tests do not constitute model training or clinical validation.</p>'+extra+'<table><tr><th>Branch</th><th>Implemented state</th><th>Remaining</th></tr>'+rows+'</table><p><a href="summary.json">Full status</a></p></html>'
(out/'index.html').write_text(page,encoding='utf-8')
lines=['# Additional specialist branches','', 'Updated 10 October 2026. These are separate tasks, with separate data, models and evaluations. No additional specialist is independently qualified. The user confirmed no additional CT/vascular/longitudinal data is currently available.','', '| Branch | State | Remaining |','|---|---|---|']
lines += [f'| {r["name"]} | {r["status"]} | {r["remaining"]} |' for r in registry['specialists']]
lines += ['', '## Implemented and tested tools','- `scripts/import_ct_hemorrhage.py --dicom-root PATH --labels CSV --output FRESH_FOLDER`: validates complete six-label targets, CT/HU preparation and patient grouping. Requires authorized local data. Then use `scripts/train_ct_hemorrhage.py --manifest IMPORT/manifest.json --output FRESH_RUN` for the implemented six-output CT CNN baseline. The trainer rejects patient leakage and never loads holdout arrays. No real CT training has occurred because the dataset is absent.','- `src/neurofusion/specialist_inputs.py`: validates CTA/MRA physical target locations and computes registered same-patient binary mask change. Millimeter units are required. Neither is a learned aneurysm or new-lesion detector.','- `scripts/train_eeg_pilot.py` and `verify_eeg_pilot.py`: six-channel temporal CNN, patient-separated training/validation and event metrics. Re-run only with a fresh experiment configuration; existing evidence is preserved.','', '## EEG dataset and limitations','Official CHB-MIT v1.0.0: https://physionet.org/content/chbmit/1.0.0/ . Open Data Commons Attribution License v1.0. Cite Guttag (2010), DOI 10.13026/C2K01R, and Shoeb (2009). Source records checked against publisher SHA256. Downloads use the official public physionet-open S3 mirror with validated byte ranges.','', 'Cases chb01–chb04 train; chb05–chb06 validate. First lexicographic seizure-free and seizure-containing recording per case. Case chb21 is known to be the same patient as chb01 and is mapped accordingly. No random window split across a patient. Positive selection enriches the cohort: pilot event sensitivity and false alarms cannot be extrapolated to a general screening population.','', 'Fixed 4-second nonoverlapping windows; six bipolar channels; causal 0.5–40 Hz filtering and decimation from 256 to 128 Hz; no normalization fit on validation. Final epoch 10, fixed threshold 0.5. Alarms require window-end observation. Matching uses positive window-interval overlap, so a detection can arrive after a short seizure ends. Latencies must not be interpreted as zero-delay detection.','', '## Data access and branch requirements','RSNA ICH data: https://www.kaggle.com/c/rsna-intracranial-hemorrhage-detection/data . Access subject to competition/data-use terms; full archive is large. Obtain permitted data, retain source metadata and patient/exam identities, audit duplicates, then train and evaluate six-label classification. Do not claim segmentation from image-level labels.','', 'RSNA aneurysm source: https://mira.rsna.org/dataset/7 . Download access was not verified here. Require approved modality/label contract, physical coordinate semantics, patient mapping, negatives and localization references before training.','', 'Longitudinal: matched visits, dates/order, consistent labels and independently checked registration are prerequisites. MSSEG-2 is a candidate source (https://portal.fli-iam.irisa.fr/msseg-2/); no access was verified. Existing unrelated MRI subjects cannot be converted into longitudinal pairs.','', 'Other planned datasets/targets retain their contracts in configs/additional_specialists.json. No placeholder or randomly initialized network counts as a trained specialist.','', '## Next work','Obtain authorized CT and vascular data; acquire verified longitudinal pairs; expand EEG beyond this pilot. For each branch, freeze patient-disjoint roles and evaluation definitions before training. Record every failed result, calibration limits and independently tested performance before integration.']
if 'eeg_pilot' in registry:
    r=registry['eeg_pilot'];lines+=['', '## Measured EEG pilot result',f'Matched events: {r["matched_events"]}/{r["reference_events"]}; false alarms/background hour: {r["false_alarms_per_background_hour"]:.3f}. Validation recording hours: {r["validation_duration_hours"]:.2f}. Independent qualification: false.']
(root/'docs/ADDITIONAL_SPECIALISTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Published truthful specialist status')
